// Maximum Subarray - Kadane's Algorithm
var array = AnimatedArray<Int>()
array.append(-2)
array.append(1)
array.append(-3)
array.append(4)
array.append(-1)
array.append(2)
array.append(1)

func maxSubArray(arr: inout AnimatedArray<Int>) -> Int {
    guard !arr.isEmpty else { return 0 }

    var currentSum = arr.at(0) ?? 0
    var maxSum = currentSum

    for i in 1..<arr.count {
        if let val = arr.at(i) {
            currentSum = max(val, currentSum + val)
            maxSum = max(maxSum, currentSum)
        }
    }
    return maxSum
}

let maxVal = maxSubArray(arr: &array)
